using namespace std;
vector<int> kLargest(vector<int>&a, int k) {
    priority_queue<int, vector<int>, greater<int>>h;
    for (int x:a) {
        h.push(x);
        if ((int)h.size()>k)h.pop();
    }
    vector<int>r;
    while (!h.empty()) {
        r.push_back(h.top());
        h.pop();
    }
    return r;
}

